using System;
using System.Collections.Generic;
using System.Linq;
using Jellyfin.Server;
using MediaBrowser.Controller;
using Microsoft.Extensions.DependencyInjection;
using Moq;
using Xunit;

namespace Jellyfin.Server.Tests
{
    public class CoreAppHostTests
    {
        [Fact]
        public void RegisterServices_ShouldRegisterIJellyfinDatabaseProvider()
        {
            // Arrange
            var serviceCollectionMock = new Mock<IServiceCollection>();
            var appHost = new CoreAppHost(
                Mock.Of<IServerApplicationPaths>(),
                Mock.Of<ILoggerFactory>(),
                Mock.Of<IStartupOptions>(),
                Mock.Of<IConfiguration>());

            // Act
            appHost.RegisterServices(serviceCollectionMock.Object);

            // Assert
            var registeredServices = serviceCollectionMock.Object.ToList();
            Assert.Contains(registeredServices, service => service.ServiceType == typeof(IJellyfinDatabaseProvider));
        }
    }
}
```

